const read=(s,n,id)=>s.repository.transaction(false,t=>id?t.get(n,id):t.all(n));
async function fixture(){
 const f=await formationFixture();await runFormation(f);const entry=(await rows(f.s,'thoughts'))[0],topic=(await rows(f.s,'topics'))[0],p=(await rows(f.s,'placements'))[0];
 await f.s.placeEntry({topicId:topic.id,entryId:entry.id,expectedEntryRevision:entry.revision,expectedTopicRevision:topic.organizationRevision,expectedPlacementRevision:p.revision,operationId:op()});
 const section=(await rows(f.s,'sections'))[0];await f.s.renameTopic({id:topic.id,expectedRevision:topic.revision,name:'SYNTHETIC changed human interpretation',operationId:op()});
 const options={scope:'synthetic-structural',contractVersion:'synthetic-1',routeVersion:'synthetic-structural-1',cursor:'aiu:delta:pending:'+JSON.stringify(['placement',p.id])},caller=Object.freeze({id:op()}),abort=new AbortController(),state={payloadAllowed:true,qualificationAllowed:true,providerHook:null,processingHook:null,evidenceHook:null},calls=[],scopes=[],expiry=Date.now()+600000;
 const authority=async(_t,r)=>({allowed:true,consentEpoch:'synthetic-consent',principalId:'synthetic-principal',libraryId:'synthetic-library',jobTypes:['AI_MAINTENANCE'],scope:{evidenceKeys:r.evidenceKeys,coverage:r.coverage}}),processing={resolve:async(_t,scope)=>{scopes.push(structuredClone(scope));return {version:1,store:f.s,caller,scope:scope.purpose==='ai-maintenance-payload'&&state.processingHook?state.processingHook(structuredClone(scope)):scope,epoch:'synthetic-processing',processing:scope.purpose==='ai-maintenance-qualification'?state.qualificationAllowed:state.payloadAllowed,expiresAt:expiry,revocationSignal:abort.signal};},isCurrent:r=>(r.scope.purpose==='ai-maintenance-qualification'?state.qualificationAllowed:state.payloadAllowed)&&!abort.signal.aborted};
 const verifier={verify:async(_caller,store,scope)=>({version:1,store,scope,accountId:'synthetic-account',processorId:'synthetic-processor',authorizationGeneration:1,processing:state.payloadAllowed,expiresAt:expiry,revocationSignal:abort.signal}),isCurrent:()=>state.payloadAllowed&&!abort.signal.aborted};
 const provider={describe:()=>({providerId:'synthetic-structural',version:'1',executionKind:'fixture'}),execute:async request=>{calls.push(structuredClone(request));await state.providerHook?.(request);return {accepted:true,operationReceiptId:'synthetic-'+request.childOperationId,body:'SYNTHETIC Context grounded in actual Input'};}};
 const service={version:1,topic:{resolveProcessing:async(_t,r)=>({allowed:true,epoch:'synthetic-topic-processing',inputIds:r.inputIds,topicIds:r.topicIds}),decisionVersion:'synthetic-1',parameters},context:{caller,processingVerifier:verifier},responseAdapter:{topic:async()=>{throw Error('Topic rename is not Topic formation');},context:async(response,metadata,binding)=>{const evidence=[],scope=await readContextTopicScope(f.s,{topicId:topic.id});assert.equal(scope.available,true);for(const inputId of metadata.inputIds){const input=await f.s.repository.transaction(false,t=>inputProjection(f.s,t,inputId));evidence.push({topicId:topic.id,inputId,selectedFields:['body'],fieldDigests:{body:await hashText(input.body)},expectedTopicBinding:scope.binding,expectedRemovalSequence:input.lastRemovalSequence,...(metadata.structuralTopics?{humanTopic:metadata.structuralTopics[0]}:{})});}await state.evidenceHook?.(evidence);return {binding,value:[{units:metadata.units,change:{operationId:op(),epoch:scope.binding.epoch,itemId:op(),card:'info',expectedRevision:0,body:response.body,section:'Synthetic',associationIds:[op()],evidence}}]};}}};
 const make=()=>{let grant;return new LocalMaintenanceSession(f.s,{authority,processing,provider,service,window:{acquire:async r=>grant=Object.freeze({version:1,kind:'fixture',dayId:'synthetic-day',windowId:op(),reservationId:op(),tier:'free',requestDigest:r.requestDigest,revocationSignal:abort.signal}),isCurrent:r=>r===grant}});};
 return {...f,entry,topic,section,p,options,state,calls,scopes,abort,authority,provider,service,processing,make,session:make()};
}
const acks=async f=>(await rows(f.s,'organizerWorkItems')).filter(r=>r.state==='ACKNOWLEDGED');
test('genuine Topic rename executes original Context with exact Topic ACK and no human organization writes',async()=>{
 const f=await fixture(),before=await Promise.all(['records','blocks','thoughts','topics','sections','placements'].map(n=>rows(f.s,n))),h=await f.session.prepare(f.options),r=await f.session.run(h);
 assert.equal(r.processedState,'COMMITTED',JSON.stringify(r));assert.equal(f.calls.length,1);assert.equal(f.calls[0].material.structuralTopics[0].name,'SYNTHETIC changed human interpretation');assert.deepEqual(f.scopes.find(s=>s.purpose==='ai-maintenance-payload').structuralTopics[0].selectedFields,['name']);assert.equal(f.calls[0].material.inputs.length,1);assert.deepEqual((await acks(f)).map(x=>[x.unit.key,x.unit.facet]),[[JSON.stringify(['topic',f.topic.id]),'context']]);assert.equal((await read(f.s,'meta',CONTEXT_CARDS_ROW)).items.length,1);assert.deepEqual(await Promise.all(['records','blocks','thoughts','topics','sections','placements'].map(n=>rows(f.s,n))),before);assert.equal((await rows(f.s,'organizerWorkItems')).filter(r=>r.state==='DEFERRED').length,1);f.session.dispose();
});

import {readTopicContext,topicContextAllowsTopic,topicContextEvidence,TOPIC_CONTEXT_LIMIT} from '../core/ai-usage/topic-context-mapping.js';
async function mapped(f){const d=(await rows(f.s,'meta')).find(r=>r.id.startsWith('aiu:delta:pending:')&&r.descriptor?.kind==='topic').descriptor;return f.s.repository.transaction(false,t=>readTopicContext(f.s,t,d));}
test('genuine Topic owner journal and complete human membership qualify exact name scope',async()=>{const f=await fixture(),m=await mapped(f);assert.ok(m);assert.deepEqual(m.selectedFields,['name']);assert.equal(m.entries.length,1);assert.equal(m.topicId,f.topic.id);f.session.dispose();});
async function rename(f,name){const row=await read(f.s,'topics',f.topic.id);return f.s.renameTopic({id:row.id,expectedRevision:row.revision,name,operationId:op()});}
for(const defect of ['derived','type','formation','entry-title','entry-note','ai-membership','missing-journal','missing-receipt','forged-journal','inactive-layout','section-rank','section-removed','cosmetic','case-only','empty'])test('Topic mapper refuses '+defect+' without inventing a supported subset',async()=>{
 const f=await fixture();if(defect==='cosmetic')await rename(f,'  SYNTHETIC changed human interpretation  ');else if(defect==='case-only')await rename(f,'synthetic changed human interpretation');else await f.s.repository.transaction(true,async t=>{const e=await t.get('thoughts',f.entry.id),p=await t.get('placements',f.p.id),section=await t.get('sections',f.section.id),topic=await t.get('topics',f.topic.id);if(defect==='derived')e.provenanceType='ai_derived';if(defect==='type')e.fieldRevisions.type=1;if(defect==='formation')e.formation='synthesized';if(defect==='entry-title')e.title='SYNTHETIC separately authored title';if(defect==='entry-note')e.note='SYNTHETIC separately authored note';if(defect==='ai-membership')p.membershipAuthorship='ai';if(defect==='inactive-layout')topic.activeLayoutGeneration++;if(defect==='section-rank')section.rank='000000000099';if(defect==='section-removed')section.lifecycle='removed';if(['missing-journal','missing-receipt','forged-journal'].includes(defect)){const d=(await t.all('meta')).find(r=>r.id.startsWith('aiu:delta:pending:')&&r.descriptor?.kind==='topic').descriptor,j=await t.get('revisions',d.journalId);if(defect==='forged-journal'){j.before.summary='SYNTHETIC unexplained lost field';await t.put('revisions',j);}else await t.delete(defect==='missing-journal'?'revisions':'operationReceipts',defect==='missing-journal'?j.id:j.operationId);}await t.put('thoughts',e);await t.put('placements',p);await t.put('sections',section);await t.put('topics',topic);if(defect==='empty')await t.delete('placements',p.id);});
 assert.equal(await mapped(f),null);const r=await f.session.run(await f.session.prepare(f.options));assert.equal(r.state,'DEFERRED',JSON.stringify(r));assert.equal(r.remainingWork,true);assert.equal(f.calls.length,0);assert.equal((await acks(f)).length,0);f.session.dispose();
});
test('Topic mapper counts complete membership across all Sections before its bound',async()=>{const f=await fixture();await f.s.repository.transaction(true,async t=>{const p=await t.get('placements',f.p.id);for(let i=0;i<TOPIC_CONTEXT_LIMIT;i++){const entryId=op();await t.put('placements',{...p,entryId,id:JSON.stringify([p.topicId,p.layoutGeneration,entryId]),sectionId:op(),rank:String(i+1).padStart(12,'0')});}});assert.equal(await mapped(f),null);f.session.dispose();});

import {captureContextEvidence,fenceContextLineage,releaseContextLineage,readableContextItems,contextEvidenceIdentity,validContextEvidenceSpecs} from '../core/context-item-lineage.js';
import {ContextMaintenanceService,CONTEXT_MAINTENANCE_LIMITS} from '../core/context-maintenance.js';
import {AIUsageFoundation} from '../core/ai-usage/foundation.js';
import {readMaintenanceBatch} from '../core/ai-usage/maintenance-batch.js';
import {TopicFormationService} from '../core/topic-formation.js';
async function evidence(f){const m=await mapped(f);assert.ok(m);const topic=await read(f.s,'topics',m.topicId),scope=await readContextTopicScope(f.s,{topicId:m.topicId}),result=[];for(const inputId of new Set(m.entries.map(e=>e.inputId))){const p=await f.s.repository.transaction(false,t=>inputProjection(f.s,t,inputId));result.push({topicId:m.topicId,inputId,selectedFields:['body'],fieldDigests:{body:await hashText(p.body)},expectedTopicBinding:scope.binding,expectedRemovalSequence:p.lastRemovalSequence,humanTopic:topicContextEvidence(m,{name:await hashText(topic.name)})});}return result;}
for(const refusal of ['denied','missing-topic','wrong-field','wrong-operation','wrong-membership'])test('independent structural processing '+refusal+' refuses before title hash and dispatch',async()=>{
 const f=await fixture();if(refusal==='denied')f.state.payloadAllowed=false;f.state.processingHook=s=>{if(refusal==='missing-topic')delete s.structuralTopics;if(refusal==='wrong-field')s.structuralTopics[0].selectedFields=['body'];if(refusal==='wrong-operation')s.structuralTopics[0].operationId=op();if(refusal==='wrong-membership')s.structuralTopics[0].entries=[];return s;};const proto=Object.getPrototypeOf(crypto.subtle),digest=proto.digest;let hashes=0;proto.digest=function(a,b){if(new TextDecoder().decode(b)==='SYNTHETIC changed human interpretation')hashes++;return digest.call(this,a,b);};try{const r=await f.session.run(await f.session.prepare(f.options));assert.notEqual(r.processedState,'COMMITTED');assert.equal(hashes,0);assert.equal(f.calls.length,0);assert.equal((await acks(f)).length,0);}finally{proto.digest=digest;f.session.dispose();}
});
for(const defect of ['missing-structure','wrong-operation','wrong-hash','missing-body','wrong-topic'])test('adapter '+defect+' cannot ACK checked structural evidence',async()=>{
 const f=await fixture();f.state.evidenceHook=async e=>{if(defect==='missing-structure')delete e[0].humanTopic;if(defect==='wrong-operation')e[0].humanTopic.operationId=op();if(defect==='wrong-hash')e[0].humanTopic.fieldDigests.name='0'.repeat(64);if(defect==='missing-body'){e[0].selectedFields=['note'];e[0].fieldDigests={note:await hashText('')};}if(defect==='wrong-topic')e[0].topicId=op();};const r=await f.session.run(await f.session.prepare(f.options));assert.notEqual(r.processedState,'COMMITTED');assert.equal(f.calls.length,1);assert.equal((await acks(f)).length,0);assert.equal((await read(f.s,'meta',CONTEXT_CARDS_ROW))?.items.length??0,0);f.session.dispose();
});

for(const boundary of ['title-hash','final-input-fence','commit-title','commit-input','commit-source','ack-title','ack-input','ack-source'])test('structural '+boundary+' drift is refused by the original shared final transaction',async()=>{
 const f=await fixture(),h=await f.session.prepare(f.options),proto=Object.getPrototypeOf(crypto.subtle),digest=proto.digest,check=TopicFormationService.prototype.checkMaterial,tx=f.s.repository.transaction.bind(f.s.repository);let hit=false,checks=0;
 if(boundary==='title-hash')proto.digest=async function(a,b){const result=await digest.call(this,a,b);if(!hit&&new TextDecoder().decode(b)==='SYNTHETIC changed human interpretation'){hit=true;await rename(f,'SYNTHETIC latest title during hash');}return result;};
 if(boundary==='final-input-fence')TopicFormationService.prototype.checkMaterial=async function(handle,final){if(final&&++checks===2)return check.call(this,handle,async t=>{const get=t.get.bind(t);t.get=async(n,id)=>{const r=await get(n,id);if(n==='blocks'&&id===f.entry.workingInputId){hit=true;r.value.libraryText='SYNTHETIC unjournaled late Input';}return r;};return final(t);});return check.call(this,handle,final);};
 if(boundary.startsWith('commit-')||boundary.startsWith('ack-'))f.s.repository.transaction=(write,fn,...rest)=>tx(write,async t=>{if(write){const put=t.put.bind(t);t.put=async(n,row,...more)=>{const result=await put(n,row,...more);if(!hit&&(boundary.startsWith('ack-')?n==='organizerWorkItems'&&row.state==='ACKNOWLEDGED':n==='meta'&&row.id===CONTEXT_CARDS_ROW)){hit=true;if(boundary.endsWith('-title')){const s=await t.get('topics',f.topic.id);s.name='SYNTHETIC late title';await put('topics',s);}else if(boundary.endsWith('-input')){const input=await t.get('blocks',f.entry.workingInputId);input.value.libraryText='SYNTHETIC late Input';await put('blocks',input);}else{const ix=await t.get('recordIndex',f.entry.sourceRecordIds[0]);await put('tombstones',{id:'source:'+ix.sourceKey});}}return result;};}return fn(t);},...rest);
 try{const r=await f.session.run(h);assert.equal(hit,true);assert.notEqual(r.processedState,'COMMITTED');assert.equal(f.calls.length,boundary.startsWith('commit-')||boundary.startsWith('ack-')?1:0);assert.equal((await acks(f)).length,0);assert.equal((await read(f.s,'meta',CONTEXT_CARDS_ROW))?.items.length??0,0);assert.equal((await rows(f.s,'operationReceipts')).filter(r=>r.id.startsWith('context-maintenance:')).length,0);}finally{proto.digest=digest;TopicFormationService.prototype.checkMaterial=check;f.s.repository.transaction=tx;f.session.dispose();}
});
test('new selected Topic name is changed interpretation evidence for original Context UPDATE, and old lineage becomes unreadable',async()=>{
 const f=await fixture();await f.session.run(await f.session.prepare(f.options));const item=(await read(f.s,'meta',CONTEXT_CARDS_ROW)).items[0],old=item.maintenance.provenance,oldCapture=await captureContextEvidence(f.s,await evidence(f),{epoch:old.epoch});
 await rename(f,'SYNTHETIC new current interpretation');await assert.rejects(fenceContextLineage(f.s,oldCapture.captured),{code:'CONTEXT_INVALIDATED'});releaseContextLineage(oldCapture.captured);const hidden=await readableContextItems(f.s,[item],{epoch:old.epoch});assert.equal(hidden.items.length,0);releaseContextLineage(hidden.captured);
 const fresh=await evidence(f),newCapture=await captureContextEvidence(f.s,fresh,{epoch:old.epoch});assert.notEqual(contextEvidenceIdentity(old),contextEvidenceIdentity(newCapture.provenance));releaseContextLineage(newCapture.captured);const expiry=Date.now()+600000,scopes=[],owner=new ContextMaintenanceService(f.s,{processingVerifier:{verify:async(_c,store,scope)=>{scopes.push(scope);return {version:1,store,scope,accountId:'synthetic-account',processorId:'synthetic-processor',authorizationGeneration:1,processing:true,expiresAt:expiry,revocationSignal:f.abort.signal};},isCurrent:()=>true}});
 const r=await owner.maintain({}, {operationId:op(),epoch:old.epoch,itemId:item.id,card:item.card,expectedRevision:item.revision,body:'SYNTHETIC corrected Context',section:item.section,associationIds:item.maintenance.associationIds,evidence:fresh});assert.equal(r.disposition,'updated');assert.equal(r.revision,2);assert.deepEqual(scopes[0].structuralTopics[0].selectedFields,['name']);assert.equal((await read(f.s,'meta',CONTEXT_CARDS_ROW)).items[0].body,'SYNTHETIC corrected Context');f.session.dispose();
});

for(const changed of [false,true])test('historical structural DEFER '+(changed?'requalifies only exact Context on a new route':'stays pending on the same route'),async()=>{
 const f=await fixture(),ai=new AIUsageFoundation(f.s,{resolveAuthority:f.authority}),batch=await readMaintenanceBatch(ai,f.options),job=await ai.plan(batch.request),groups=[];await ai.read(async t=>{const saved=await ai.job(t,job.id);for(let i=0;i<saved.childIds.length;i++)for(const facet of ['topic','context']){const units=saved.childCoverage[i].filter(u=>u.facet===facet);if(units.length)groups.push({childId:saved.childIds[i],facet,units,retryCondition:facet==='topic'?'TOPIC_MAPPING_UNAVAILABLE':'CONTEXT_MAPPING_UNAVAILABLE'});}});await ai.deferMaintenanceBeforeDispatch(job.id,{groups},{signal:f.abort.signal,isCurrent:()=>true,plan:job});const oldJob=await read(f.s,'organizerJobs',job.id),deferred=(await rows(f.s,'organizerWorkItems')).filter(r=>r.state==='DEFERRED');await f.session.run(await f.session.prepare({...f.options,routeVersion:changed?'synthetic-new-structural-route':f.options.routeVersion}));for(const d of deferred){if(changed&&d.unit.facet==='context'){const history=await read(f.s,'organizerWorkItems','aiu:defer-history:'+d.id.slice('aiu:defer:'.length));assert.equal(history.reconsideredBecause,'HUMAN_TOPIC_CONTEXT_MAPPER_V1');assert.equal(history.originalId,d.id);}else assert.deepEqual(await read(f.s,'organizerWorkItems',d.id),d);}assert.deepEqual(await read(f.s,'organizerJobs',job.id),oldJob);assert.equal(f.calls.length,changed?1:0);assert.equal((await acks(f)).length,changed?1:0);f.session.dispose();
});
test('exact structural ACK abort rolls back Context and retry consumes only the original response',async()=>{
 const f=await fixture(),tx=f.s.repository.transaction.bind(f.s.repository);let hit=false;f.s.repository.transaction=(write,fn,...rest)=>tx(write,async t=>{if(write){const put=t.put.bind(t);t.put=async(n,row,...more)=>{const r=await put(n,row,...more);if(!hit&&n==='organizerWorkItems'&&row.state==='ACKNOWLEDGED'&&row.unit.facet==='context'){hit=true;throw Error('Synthetic ACK abort');}return r;};}return fn(t);},...rest);try{const h=await f.session.prepare(f.options),first=await f.session.run(h);assert.equal(hit,true);assert.equal(first.state,'PARTIAL');assert.equal((await acks(f)).length,0);assert.equal((await read(f.s,'meta',CONTEXT_CARDS_ROW))?.items.length??0,0);assert.equal((await f.session.run(h)).processedState,'COMMITTED');assert.equal(f.calls.length,1);assert.equal((await acks(f)).length,1);}finally{f.s.repository.transaction=tx;f.session.dispose();}
});
for(const deny of [false,true])test('mixed independent Topic then unchanged Topic-name Context '+(deny?'requires a fresh independent title grant':'uses the original two-child envelope'),async()=>{
 const f=await fixture();await inputEdit(f.s,f.entry.workingInputId,{libraryText:'SYNTHETIC fresh original Input'});f.session.dispose();const execute=f.provider.execute;
 f.provider.execute=async request=>{if(!request.coverage.some(u=>u.facet==='topic'))return execute(request);f.calls.push(structuredClone(request));const view={...request.material,inputs:request.material.inputs.map(i=>({id:i.inputId,role:'primary',fields:{body:i.body},revision:i.revision})),entries:[]},proposed=assessment(view,{name:'Synthetic existing subject',evidence:view.inputs.map(i=>citation(i)),entries:view.inputs.map(i=>({span:citation(i),type:'idea',additional:[]}))});return JSON.parse(JSON.stringify({accepted:true,operationReceiptId:'synthetic-topic-'+request.childOperationId,proposed,body:'SYNTHETIC first Context'}));};f.service.responseAdapter.topic=async(response,_view,binding)=>({binding,value:response.proposed});if(deny)f.state.processingHook=scope=>{if(scope.structuralTopics)delete scope.structuralTopics;return scope;};f.session=f.make();
 const h=await f.session.prepare({...f.options,cursor:null}),r=await f.session.run(h);assert.equal(h.childCount,2);assert.equal(f.calls.length,deny?1:2,JSON.stringify(r));assert.equal(f.calls[0].material.structuralTopics,undefined);const exact=(await acks(f)).filter(a=>a.unit.key===JSON.stringify(['topic',f.topic.id]));if(deny){assert.equal(r.state,'UNAVAILABLE',JSON.stringify(r));assert.equal(exact.length,0);}else{assert.equal(r.processedState,'COMMITTED',JSON.stringify(r));assert.equal(exact.length,1);assert.ok(f.calls[1].coverage.every(u=>u.facet==='context'));assert.equal(f.calls[1].material.structuralTopics[0].topicOrganizationRevision,(await read(f.s,'topics',f.topic.id)).organizationRevision);await f.session.run(h);assert.equal(f.calls.length,2);}f.session.dispose();
});

