for(const operation of ['maintain','noChange','invalidate'])for(const target of ['title','input','source'])test('direct original Context '+operation+' fences structural '+target+' after its staged receipt',async()=>{
 const f=await fixture(),fresh=await evidence(f),owner=new ContextMaintenanceService(f.s,{processingVerifier:f.service.context.processingVerifier}),caller={},change={operationId:op(),epoch:fresh[0].expectedTopicBinding.epoch,itemId:op(),card:'info',expectedRevision:0,body:'SYNTHETIC standalone Context',section:'Synthetic',associationIds:[op()],evidence:fresh};
 if(operation!=='maintain'){const created=await owner.maintain(caller,change);assert.equal(created.disposition,'created');}
 const request=operation==='maintain'?change:{operation:operation==='noChange'?'NO_CHANGE':'REMOVE_CANDIDATE',operationId:op(),epoch:change.epoch,itemId:change.itemId,card:change.card,expectedRevision:1,associationIds:change.associationIds,evidence:fresh},stores=['meta','operationReceipts','topics','sections','blocks','tombstones'],before=await Promise.all(stores.map(n=>rows(f.s,n))),tx=f.s.repository.transaction.bind(f.s.repository);let hit=false;
 f.s.repository.transaction=(write,fn,...rest)=>tx(write,async t=>{if(write){const put=t.put.bind(t);t.put=async(n,row,...more)=>{const result=await put(n,row,...more);if(!hit&&n==='operationReceipts'&&row.id==='context-maintenance:'+request.operationId){hit=true;if(target==='title'){const section=await t.get('topics',f.topic.id);section.name='SYNTHETIC late owner title';await put('topics',section);}else if(target==='input'){const input=await t.get('blocks',f.entry.workingInputId);input.value.libraryText='SYNTHETIC late owner Input';await put('blocks',input);}else{const ix=await t.get('recordIndex',f.entry.sourceRecordIds[0]);await put('tombstones',{id:'source:'+ix.sourceKey});}}return result;};}return fn(t);},...rest);
 try{await assert.rejects(owner[operation](caller,request),{code:'CONTEXT_INVALIDATED'});assert.equal(hit,true);}finally{f.s.repository.transaction=tx;f.session.dispose();}
 assert.deepEqual(await Promise.all(stores.map(n=>rows(f.s,n))),before);assert.equal(await read(f.s,'operationReceipts','context-maintenance:'+request.operationId),undefined);
});

for(const drift of [null,'title','input','source'])test('original structural NO_CHANGE final settlement '+(drift?'rejects counter-tail '+drift+' drift':'preserves a checked-subset positive control'),async()=>{
 const f=await fixture();assert.equal((await f.session.run(await f.session.prepare(f.options))).processedState,'COMMITTED');f.session.dispose();const item=(await read(f.s,'meta',CONTEXT_CARDS_ROW)).items[0];await rename(f,'SYNTHETIC next checked interpretation');
 const adapter=f.service.responseAdapter.context;let operationId;f.service.responseAdapter.context=async(...args)=>{const result=await adapter(...args);for(const group of result.value){group.operation='NO_CHANGE';const c=group.change;delete c.body;delete c.section;Object.assign(c,{operation:'NO_CHANGE',itemId:item.id,expectedRevision:item.revision,associationIds:item.maintenance.associationIds});operationId=c.operationId;}return result;};f.session=f.make();const h=await f.session.prepare(f.options),priorAcks=await acks(f),priorCounters=await read(f.s,'meta','aiu:counters:v1'),section=await read(f.s,'topics',f.topic.id),tx=f.s.repository.transaction.bind(f.s.repository);let hit=false;
 f.s.repository.transaction=(write,fn,...rest)=>tx(write,async t=>{if(write){const put=t.put.bind(t);t.put=async(n,row,...more)=>{const result=await put(n,row,...more);if(!hit&&n==='meta'&&row.id==='aiu:counters:v1'&&row.localResolved>(priorCounters?.localResolved||0)){hit=true;if(drift==='title'){const s=await t.get('topics',f.topic.id);s.name='SYNTHETIC stale after all settlement writes';await put('topics',s);}else if(drift==='input'){const i=await t.get('blocks',f.entry.workingInputId);i.value.libraryText='SYNTHETIC late settlement Input';await put('blocks',i);}else if(drift==='source'){const ix=await t.get('recordIndex',f.entry.sourceRecordIds[0]);await put('tombstones',{id:'source:'+ix.sourceKey});}}return result;};}return fn(t);},...rest);
 let result;try{result=await f.session.run(h);}finally{f.s.repository.transaction=tx;f.session.dispose();}
 assert.equal(hit,true,JSON.stringify(result));assert.equal(f.calls.length,2);assert.deepEqual((await read(f.s,'meta',CONTEXT_CARDS_ROW)).items,[item]);assert.deepEqual(await read(f.s,'topics',f.topic.id),section);
 if(drift){assert.notEqual(result.processedState,'COMMITTED',JSON.stringify(result));assert.deepEqual(await acks(f),priorAcks);assert.equal(await read(f.s,'operationReceipts','context-maintenance:'+operationId),undefined);assert.equal((await read(f.s,'meta','aiu:counters:v1')).localResolved,priorCounters.localResolved);}else{assert.equal(result.processedState,'COMMITTED',JSON.stringify(result));assert.equal((await read(f.s,'operationReceipts','context-maintenance:'+operationId)).result.disposition,'no_change');assert.equal((await read(f.s,'meta','aiu:counters:v1')).localResolved,priorCounters.localResolved+1);assert.ok((await acks(f)).some(a=>a.outcome==='NO_CHANGE'));}
});


