async function completeTopicMembers(f,count){
 for(let n=1;n<count;n++){
  const prior=new Set((await rows(f.s,'inputStates')).map(i=>i.id));await f.s.capture(capture((await f.s.status()).epoch,op(),'SYNTHETIC exact short original member '+n));const input=(await rows(f.s,'inputStates')).find(i=>!prior.has(i.id));
  const formation=new TopicFormationService(f.s,{...f.serviceOptions,decision:{version:'synthetic-boundary',assess:view=>assessment(view,{relations:view.identities.map(x=>({topicId:x.canonicalId,relation:'same',citations:[citation(view.inputs[0])]}))})},parameters}),prepared=await formation.prepare({scope:[{inputId:input.id,role:'primary',selectedFields:['body']}],operationId:op()});await formation.commit(prepared);
  const topic=await read(f.s,'topics',f.topic.id),entry=(await rows(f.s,'thoughts')).find(e=>e.workingInputId===input.id),placement=(await rows(f.s,'placements')).find(p=>p.entryId===entry.id&&p.topicId===topic.id);assert.equal(entry.provenanceType,'input_original');await f.s.placeEntry({topicId:topic.id,entryId:entry.id,expectedEntryRevision:entry.revision,expectedTopicRevision:topic.organizationRevision,...(placement?{expectedPlacementRevision:placement.revision}:{}),operationId:op()});
 }
 await rename(f,'SYNTHETIC complete bounded Topic');
}
