import {authoredContextEvidence} from '../core/context-authored-entry.js';
import {boundContextEvidence} from '../core/context-bound-entry.js';
async function mixedAuthoredTopic(count){
 const f=await fixture();await completeTopicMembers(f,count===1?1:6);const topic=await f.s.createTopic({name:'SYNTHETIC separate authored members',operationId:op()}),humans=[];
 for(let i=0;i<count;i++){const entry=await f.s.createEntry({actor:'user',operationId:op(),body:'SYNTHETIC independent author '+i,type:'idea',formation:'explicit',evidence:[]});await f.s.placeEntry({topicId:topic.id,entryId:entry.id,expectedEntryRevision:entry.revision,expectedTopicRevision:(await f.s.topic(topic.id)).organizationRevision,operationId:op()});humans.push(entry);}
 f.service.responseAdapter.context=async(response,metadata,binding)=>{const evidence=[];for(const inputId of metadata.inputIds){const structural=metadata.structuralTopics?.find(s=>s.entries.some(e=>e.inputId===inputId)),target=structural?.topicId??metadata.boundEntries?.find(e=>e.inputId===inputId)?.topicId??metadata.placements?.find(e=>e.inputId===inputId)?.topicId??f.topic.id,scope=await readContextTopicScope(f.s,{topicId:target}),input=await f.s.repository.transaction(false,t=>inputProjection(f.s,t,inputId));assert.equal(scope.available,true);evidence.push({topicId:target,inputId,selectedFields:['body'],fieldDigests:{body:await hashText(input.body)},expectedTopicBinding:scope.binding,expectedRemovalSequence:input.lastRemovalSequence,...(structural?{humanTopic:structural}:{})});}
 for(const entry of metadata.authoredEntries||[]){const scope=await readContextTopicScope(f.s,{topicId:entry.topicId});assert.equal(scope.available,true);evidence.push(authoredContextEvidence(entry,scope.binding,entry.fieldDigests||entry.bodyDigest));}for(const entry of metadata.boundEntries||[]){const scope=await readContextTopicScope(f.s,{topicId:entry.topicId});assert.equal(scope.available,true);evidence.push(boundContextEvidence(entry,scope.binding,entry.fieldDigests));}
 return {binding,value:[{units:metadata.units,change:{operationId:op(),epoch:evidence[0].expectedTopicBinding.epoch,itemId:op(),card:'info',expectedRevision:0,body:response.body,section:'Synthetic combined',associationIds:[op()],evidence}}]};};f.session.dispose();f.session=f.make();return {...f,humans};
}
